import os, json, time, subprocess
# rc5_bs_run (block 2; Daniel 2026-11-14 14:41: Bambu Studio headless from a Fusion script). READ-ONLY on the design: it never
#   touches the Fusion document. Writes the job's assemble list and arguments (inline below, generated by mkjob.py) to
#   print_audit_recheck/slicer/jobs/<job>/, then starts Bambu Studio's command-line slicer (flattened X2D presets, oriented STLs,
#   its own --datadir inside the recheck folder), stdout/stderr to slicer/out/<job>/. Waits up to RC_WAIT s; a longer slice keeps
#   running and is polled with RC_MODE = 'poll'. Writes only in slicer/jobs/<job>/, slicer/out/<job>/ and slicer/bsdata/.
RC_DIR = os.path.expanduser('~/Documents/HA_panel_renders/print_audit_recheck')
RC_BS_BIN = '/Applications/BambuStudio.app/Contents/MacOS/BambuStudio'
RC_JOB = '__JOB__'
RC_MODE = '__MODE__'           # 'start' or 'poll'
RC_WAIT = 45
RC_ASSEMBLE = __ASSEMBLE__
RC_ARGS = __ARGS__


def rc_alive(pid):
    try:
        os.kill(pid, 0)
        return True
    except OSError:
        return False


def rc_status(outd):
    st = json.load(open(os.path.join(outd, 'started.json')))
    files = sorted(f for f in os.listdir(outd))
    res = None
    p = os.path.join(outd, 'result.json')
    if os.path.exists(p):
        try:
            res = json.load(open(p))
        except Exception:
            res = open(p).read()[:400]
    tail = open(os.path.join(outd, 'stdout.txt')).read()[-500:]
    return {'job': RC_JOB, 'pid': st['pid'], 'alive': rc_alive(st['pid']), 'elapsed_s': round(time.time() - st['t0'], 1),
            'files': files, 'result': res, 'stdout_tail': tail}


def run(_context):
    outd = os.path.join(RC_DIR, 'slicer', 'out', RC_JOB)
    if RC_MODE == 'start':
        jd = os.path.join(RC_DIR, 'slicer', 'jobs', RC_JOB); os.makedirs(jd, exist_ok=True)
        json.dump(RC_ASSEMBLE, open(os.path.join(jd, 'assemble.json'), 'w'), indent=1)
        json.dump(RC_ARGS, open(os.path.join(jd, 'args.json'), 'w'), indent=1)
        os.makedirs(outd, exist_ok=True)
        os.makedirs(os.path.join(RC_DIR, 'slicer', 'bsdata'), exist_ok=True)
        so = open(os.path.join(outd, 'stdout.txt'), 'w'); se = open(os.path.join(outd, 'stderr.txt'), 'w')
        p = subprocess.Popen([RC_BS_BIN] + RC_ARGS, stdout=so, stderr=se, stdin=subprocess.DEVNULL, cwd=outd, start_new_session=True)
        json.dump({'pid': p.pid, 't0': time.time(), 'args': RC_ARGS}, open(os.path.join(outd, 'started.json'), 'w'))
        try:
            rc = p.wait(timeout=RC_WAIT)
        except subprocess.TimeoutExpired:
            rc = None
        out = rc_status(outd); out['rc'] = rc
    else:
        out = rc_status(outd)
    print(json.dumps(out, separators=(',', ':')))
